/* Cultivation workspaces: read-only browsing, with actions owned by the existing engine. */
(()=>{'use strict';
const S=XTSandbox,Q=XTQi51,V=S.view,esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const base={render,scene:renderScene,actions:renderActions},levels=['未入门','入门','熟练','精通'];
let owner=null,ui={pane:'books',kind:'全部',query:'',selected:null,detail:false};
function syncOwner(){const id=G?.world36?.playerId;if(id!==owner){owner=id;ui={pane:'books',kind:'全部',query:'',selected:null,detail:false};}}
function button(text,fn,cls='cult-link'){const b=document.createElement('button');b.type='button';b.className=cls;b.textContent=text;b.onclick=fn;return b;}
function go(pane){ui.pane=pane;ui.detail=false;S.go('cult',pane==='practice'?'practice':'arts');}
function tabs(active){const nav=document.createElement('nav');nav.className='cult-tabs';nav.setAttribute('aria-label','修行页面');for(const [id,title]of[['practice','修炼'],['books','功法'],['loadout','配功']]){const b=button(title,()=>go(id));b.dataset.cultTab=id;b.setAttribute('aria-current',id===active?'page':'false');nav.append(b);}return nav;}
function effectRows(effect){const rows=[];for(const[key,label,unit,scale]of[['absorb','修炼效率','%',100],['bt','突破修正','%',100],['life','寿元','年',1]]){const n=effect?.[key];if(n)rows.push([label,(n>0?'+':'')+Number((n*scale).toFixed(3))+unit]);}return rows;}
function facts(rows){return '<dl class="cult-facts">'+rows.map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl>';}
function loadoutSummary(){const d=G.sandbox35||{},q=G.qi51||{};return [['主修心法',d.mind||'尚未设置'],['辅修心法',(q.aux||[]).join('、')||'尚未设置'],['已备术法',(d.spells||[]).join('、')||'尚未备入']];}
function navigationFooter(root){const nav=document.createElement('div');nav.className='cult-related';nav.append(button('传习与百艺',()=>S.dispatch('q51:routes52')),button('演练与斗法',()=>S.dispatch('q51:hub')),button('查看功法来路',()=>S.dispatch('q51:shop')));root.append(nav);}
function dashboard(scene){const guide=scene.querySelector('.qi-guide51'),p=guide?.querySelector('p'),next=p?.innerHTML.split(/<br\s*\/?\s*>/i)[0]||'按当前境界与地点安排修炼。';guide?.remove();const header=scene.querySelector('.sb-head');if(header?.querySelector('h2'))header.querySelector('h2').textContent='修炼';scene.querySelector('.sb-tabs')?.remove();const original=document.createElement('div');original.className='cult-original';const shell=scene.querySelector('.sb-shell');const scroll=shell?.querySelector('.sb-scroll');if(scroll){while(scroll.firstChild)original.append(scroll.firstChild);}else{for(const node of [...scene.children])if(node!==header)original.append(node);}
 const root=document.createElement('section');root.className='cult-ui cult-dashboard';root.dataset.cultUi='practice';root.append(tabs('practice'));const need=needOf(G.layer)||1,pct=Math.min(100,G.cult/need*100);root.insertAdjacentHTML('beforeend',`<div class="cult-practice-grid"><section class="cult-practice-main"><span class="cult-eyebrow">静修 · 积累</span><h2>${esc(curRealmTxt())}</h2><p class="cult-progress-label">修为 ${Math.floor(G.cult)} / ${need}</p><div class="cult-progress"><i style="width:${pct}%"></i></div><div class="cult-primary-actions"></div><p class="cult-action-note">修炼、闭关与突破沿用真实时间和钱物结算。</p></section><aside class="cult-current"><h3>当前配功</h3>${facts(loadoutSummary())}<button type="button" data-cult-edit>调整配功　›</button></aside></div><section class="cult-next qi-guide51"><span>下一步</span><p>${next}</p></section>`);root.querySelector('[data-cult-edit]').onclick=()=>go('loadout');const more=document.createElement('details');more.className='cult-explanation';more.innerHTML='<summary>修行见闻与当前环境</summary>';more.append(original);root.append(more);navigationFooter(root);if(scroll)scroll.append(root);else scene.append(root);
}
function loadout(root,sources){const section=document.createElement('section');section.className='cult-loadout';section.innerHTML='<div class="cult-section-head"><div><span class="cult-eyebrow">运功 · 当前配置</span><h2>功法各有所用</h2></div></div><p class="cult-muted">研习进度保留，配置只在战外调整。</p>';const rows=loadoutSummary(),grid=document.createElement('div');grid.className='cult-slot-grid';for(const[label,value]of rows){const slot=document.createElement('article');slot.className='cult-slot';slot.innerHTML='<small>'+esc(label)+'</small><h3>'+esc(value)+'</h3>';slot.append(button('选择功法　›',()=>{ui.kind=label==='已备术法'?'术法':'心法';ui.query='';go('books');}));grid.append(slot);}section.append(grid);const a=Q.auxiliary(),details=document.createElement('section');details.className='cult-loadout-effects';details.innerHTML='<h3>当前辅修结果</h3>'+facts([...effectRows(a),['每回合额外耗真元',String(a.burden||0)]])+(a.details||[]).map(x=>'<p><strong>'+esc(x.title)+'</strong><span class="cult-compat '+(x.label==='冲突'?'conflict':'')+'">'+esc(x.label)+'</span><small>'+esc(x.reason)+'</small></p>').join('');section.append(details);root.append(section);navigationFooter(root);}
function library(scene,catalog=false){const sourceKey=catalog?'catalog':'owned';if(ui.sourceKey!==sourceKey){ui.sourceKey=sourceKey;ui.query='';ui.kind='全部';ui.selected=null;ui.detail=false;}const original=scene.querySelector('.sb-scroll');if(!original?.parentNode)return;const sources=new Map();for(const b of original.querySelectorAll(catalog?'[data-sb="q51:buy"]':'[data-sb="q51:practice"]')){const article=b.closest('article');sources.set(b.dataset.arg,{actions:[...article.querySelectorAll('[data-sb]')]});}const notices=[...original.querySelectorAll('.qi-notice51')];const root=document.createElement('section');root.className='cult-ui manual-library';root.dataset.cultUi='books';if(!catalog)root.append(tabs(ui.pane==='loadout'?'loadout':'books'));else{const nav=document.createElement('div');nav.className='cult-related';nav.append(button('‹ 返回功法库',()=>go('books')),button('各路进阶传习与百艺',()=>S.dispatch('q51:routes52')));root.append(nav);}
 original.replaceChildren(root);for(const n of notices)root.append(n);const heading=scene.querySelector('.sb-head h2');if(heading)heading.textContent=catalog?'传习抄本':ui.pane==='loadout'?'配功':'功法';if(ui.pane==='loadout'&&!catalog){loadout(root,sources);return;}
 const d=G.sandbox35||{},entries=[...sources.keys()].filter(t=>MANUALS[t]);root.insertAdjacentHTML('beforeend','<div class="manual-workspace"><section class="manual-list-pane"><div class="manual-toolbar"><div class="manual-kinds"></div><label class="manual-search-wrap"><span>⌕</span><input class="manual-search" type="search" placeholder="查找功法名称" aria-label="查找功法名称"></label></div><p class="manual-count"></p><div class="manual-list"></div></section><aside class="manual-detail" aria-label="功法详情"></aside></div>');const list=root.querySelector('.manual-list'),detail=root.querySelector('.manual-detail'),search=root.querySelector('.manual-search'),kinds=root.querySelector('.manual-kinds');search.value=ui.query;
 function badge(title){if(d.mind===title)return '主修';if(G.qi51?.aux?.includes(title))return '辅修';if(d.spells?.includes(title))return '已备';if(!d.books?.[title])return '未收录';return levels[d.books[title].level||0];}
 function drawDetail(title){const m=MANUALS[title],source=sources.get(title);detail.replaceChildren();if(!m||!source){detail.innerHTML='<div class="manual-empty"><span>卷</span><h3>尚无匹配功法</h3><p>调整分类或搜索词，再选择一部查看。</p></div>';return;}const meta=Q.library[title]||m,level=d.books?.[title]?.level||0;detail.append(button('‹ 返回功法',()=>{ui.detail=false;root.classList.remove('manual-mobile-detail');},'manual-back'));detail.firstChild.dataset.manualBack='';detail.insertAdjacentHTML('beforeend',`<header class="manual-detail-head"><div class="manual-book-mark">${m.kind==='心法'?'心':'术'}</div><div><span class="cult-eyebrow">${esc(m.kind)} · ${esc(m.tier)}品</span><h2>${esc(title)}</h2><p>${catalog?'传习抄本':esc(levels[level]||'进度待查')} · ${esc(badge(title))}</p></div></header><section class="manual-purpose"><h3>功法用途</h3><p>${esc(meta.desc||m.desc||'尚无详细记载。')}</p></section>`);
 const rows=effectRows(m.effect);if(rows.length)detail.insertAdjacentHTML('beforeend','<section class="manual-effects"><h3>本法条目</h3>'+facts(rows)+'</section>');if(m.kind==='术法'){const move=Q.moveDefs[Q.moveFor(title)];if(move)detail.insertAdjacentHTML('beforeend','<section class="manual-effects"><h3>招式作用</h3><p>'+esc(move.desc)+'</p><small>实际真元消耗会受当前配功与战斗状态影响。</small></section>');}
 const why=window.XTQi52?.studyReason(title,true)||'',quote=Q.studyQuote(title),requirements=document.createElement('section');requirements.className='manual-requirements';requirements.innerHTML='<h3>'+(catalog?'取得与研习':'研习条件')+'</h3>'+(catalog?'<p>抄本须在实际传习地点购买；取得后到行囊阅读收录。</p>':'<p class="manual-cost">'+(quote.complete?'已至精通，当前研习阶段已满。':'本次需要 <strong>'+quote.fee+'灵石</strong> · <strong>'+quote.days+'日</strong>')+'</p>')+(why?'<p class="cult-blocked">'+esc(why)+'</p>':'')+(!catalog&&!quote.complete&&G.stones<quote.fee?'<p class="cult-blocked">灵石不足：持有'+esc(G.stones)+'，尚需'+esc(quote.fee-G.stones)+'灵石。</p>':'');detail.append(requirements);
 if(m.kind==='心法'&&d.mind&&d.mind!==title){const c=Q.compatibility(d.mind,title);detail.insertAdjacentHTML('beforeend','<section class="manual-compatibility"><h3>与当前主修搭配</h3><span class="cult-compat '+(c.label==='冲突'?'conflict':'')+'">'+esc(c.label)+'</span><p>'+esc(c.reason)+'</p><details><summary>辅修折算说明</summary><p>按现有品阶、熟练度和适配关系折算本法已有条目；运气冲突会产生回合真元负担。实际结果在配功页查看。</p></details></section>');}
 const actions=document.createElement('div');actions.className='manual-actions';for(const b of source.actions){if(b.dataset.sb==='q51:practice'){b.disabled=quote.complete||!!why||G.stones<quote.fee;b.textContent=quote.complete?'已至精通':(level?'继续研习':'开始入门')+' · '+quote.days+'日 / '+quote.fee+'灵石';b.classList.add('on');}if(b.dataset.sb==='q51:buy'){b.textContent='购买抄本 · '+meta.price+'灵石';b.disabled=b.disabled||G.stones<meta.price;b.classList.add('on');}actions.append(b);}detail.append(actions);const extra=document.createElement('details');extra.className='manual-source';extra.innerHTML='<summary>传承来路</summary><p>'+esc(m.from||'随身书册与既有传承')+'</p>';detail.append(extra);
 const subtitle=detail.querySelector('.manual-detail-head p');if(subtitle&&!catalog&&badge(title)===(levels[level]||''))subtitle.textContent=levels[level];if(catalog){requirements.insertAdjacentHTML('beforeend','<p class="manual-cost">抄本价格 <strong>'+esc(meta.price)+'灵石</strong> · 当前持有 '+esc(G.stones)+'灵石</p>'+(!Q.teacherHere()?'<p class="cult-blocked">当前不在传习地点。须到县城入口或道观前院当面购买。</p>':'')+(G.stones<meta.price?'<p class="cult-blocked">灵石不足，尚需'+esc(meta.price-G.stones)+'灵石。</p>':''));}
 const compatibility=detail.querySelector('.manual-compatibility');if(compatibility){const fold=document.createElement('details');fold.className='manual-compat-fold';fold.innerHTML='<summary>与主修搭配 · '+esc(Q.compatibility(d.mind,title).label)+'</summary>';compatibility.replaceWith(fold);fold.append(compatibility);}
 const body=document.createElement('div');body.className='manual-detail-body';for(const node of[...detail.children])if(node!==actions&&!node.matches('.manual-back,.manual-detail-head'))body.append(node);detail.insertBefore(body,actions);
 }
 function draw(){const visible=entries.filter(t=>(ui.kind==='全部'||MANUALS[t].kind===ui.kind)&&t.toLowerCase().includes(ui.query.trim().toLowerCase()));if(!visible.includes(ui.selected))ui.selected=visible[0]||null;list.replaceChildren();root.querySelector('.manual-count').textContent=(catalog?'可查抄本':'已收录')+' · '+visible.length+'部';for(const title of visible){const m=MANUALS[title],b=button('',()=>{ui.selected=title;ui.detail=true;draw();root.classList.add('manual-mobile-detail');if(matchMedia('(max-width:700px)').matches)document.scrollingElement.scrollTop=0;},'manual-row');b.dataset.manual=title;b.setAttribute('aria-current',title===ui.selected?'true':'false');b.innerHTML='<span class="manual-row-mark">'+(m.kind==='心法'?'心':'术')+'</span><span><strong>'+esc(title)+'</strong><small>'+esc(m.kind+' · '+m.tier+'品')+'</small></span><span class="manual-row-state">'+esc(badge(title))+'<i>›</i></span>';list.append(b);}if(!visible.length)list.innerHTML='<p class="cult-empty">暂无匹配条目。清空搜索，或查看其他分类。</p>';drawDetail(ui.selected);for(const b of kinds.querySelectorAll('button'))b.setAttribute('aria-current',b.dataset.cultKind===ui.kind?'true':'false');}
 for(const kind of['全部','心法','术法']){const b=button(kind,()=>{ui.kind=kind;ui.detail=false;root.classList.remove('manual-mobile-detail');draw();});b.dataset.cultKind=kind;kinds.append(b);}search.oninput=()=>{ui.query=search.value;ui.detail=false;root.classList.remove('manual-mobile-detail');draw();};draw();if(ui.detail)root.classList.add('manual-mobile-detail');if(!entries.length){const empty=document.createElement('p');empty.className='cult-empty';empty.textContent='尚未收录功法。先取得抄本，在行囊阅读后再来研习。';root.append(empty);root.append(button('查看传习抄本',()=>S.dispatch('q51:shop')));}
}
function moveActions(){const target=document.querySelector('.cult-primary-actions'),footer=document.getElementById('actions');if(target?.parentNode&&footer?.children){for(const node of[...footer.children])target.append(node);target.querySelector('button')?.classList.add('on');}}
function adapt(){if(!G?.root||G.mode!=='idle'||G.qi51?.battle)return;syncOwner();const scene=document.getElementById('scene');if(!scene?.parentNode||scene.querySelector('[data-cult-ui]'))return;if(V.tab==='cult'){if(V.sub==='arts')library(scene);else dashboard(scene);}else if(V.tab==='shop51')library(scene,true);}
renderScene=function(...args){const out=base.scene(...args);adapt();return out;};renderActions=function(...args){const out=base.actions(...args);moveActions();return out;};render=function(...args){const out=base.render(...args);adapt();moveActions();return out;};
window.XTCultivationUI=Object.freeze({open:go});if(G)render();
})();
